-- Shared bill splitter: initial schema.
-- All ids are UUID strings generated by the API. All money is whole cents (integers).

CREATE TABLE homes (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL
);

CREATE TABLE members (
  id TEXT PRIMARY KEY,
  home_id TEXT NOT NULL,
  name TEXT NOT NULL,
  -- Position of the member inside its home, starting at 1, in the order members
  -- were added. The split rule and the balances list both rely on this order.
  seq INTEGER NOT NULL,
  CONSTRAINT fk_members_home FOREIGN KEY (home_id) REFERENCES homes (id),
  CONSTRAINT uq_members_home_seq UNIQUE (home_id, seq)
);

CREATE TABLE bills (
  id TEXT PRIMARY KEY,
  home_id TEXT NOT NULL,
  title TEXT NOT NULL,
  total_cents INTEGER NOT NULL,
  CONSTRAINT fk_bills_home FOREIGN KEY (home_id) REFERENCES homes (id),
  CONSTRAINT chk_bills_total_positive CHECK (total_cents > 0)
);

CREATE TABLE shares (
  id TEXT PRIMARY KEY,
  bill_id TEXT NOT NULL,
  member_id TEXT NOT NULL,
  amount_cents INTEGER NOT NULL,
  -- ISO timestamp set when the share is paid; NULL means unpaid.
  paid_at TEXT,
  -- The Idempotency-Key that paid this share, if any. Stored so a retry with
  -- the same key can return the same result, and a retry with a different key
  -- can be rejected with 409.
  idempotency_key TEXT,
  CONSTRAINT fk_shares_bill FOREIGN KEY (bill_id) REFERENCES bills (id),
  CONSTRAINT fk_shares_member FOREIGN KEY (member_id) REFERENCES members (id),
  CONSTRAINT chk_shares_amount_nonnegative CHECK (amount_cents >= 0),
  CONSTRAINT uq_shares_bill_member UNIQUE (bill_id, member_id)
);
